}

int isPerfectSquare(int n) {
    if (n < 0) return 0;
    long long low = 0, high = n;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long sq = mid * mid;
        if (sq == n) return 1;
        if (sq < n) low = mid + 1;
        else high = mid - 1;
    }
    return 0;
}

